const response = $input.item.json;
const prev = $('Route Action').first().json;

let rawText = '';
if (typeof response?.output === 'string') {
  rawText = response.output;
} else if (typeof response?.text === 'string') {
  rawText = response.text;
} else if (response?.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = response.candidates[0].content.parts[0].text;
} else if (typeof response === 'string') {
  rawText = response;
} else {
  return {
    isValid: false,
    statusCode: 502,
    error: 'AI content generation service returned an invalid or empty response structure.'
  };
}

let cleaned = rawText.trim();
if (cleaned.startsWith('```json')) {
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let data = {};
try {
  data = JSON.parse(cleaned.trim());
} catch (e) {
  return {
    isValid: false,
    statusCode: 422,
    error: 'Validation error: Failed to parse Gemini output as JSON: ' + rawText.slice(0, 100)
  };
}

if (!data || typeof data !== 'object' || Array.isArray(data)) {
  return {
    isValid: false,
    statusCode: 422,
    error: 'Validation error: Output must be a non-null JSON object.'
  };
}

function isNonEmptyString(val) {
  return typeof val === 'string' && val.trim().length > 0;
}
function isStringArray(val) {
  return Array.isArray(val) && val.length > 0 && val.every(item => typeof item === 'string' && item.trim().length > 0);
}

// 1. Top-level validation
if (!isNonEmptyString(data.title)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'title' is required and must be a non-empty string." };
}
if (!isNonEmptyString(data.summary)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'summary' is required and must be a non-empty string." };
}

// 2. LinkedIn validation
if (!data.linkedin || typeof data.linkedin !== 'object' || Array.isArray(data.linkedin)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'linkedin' format object is required." };
}
const linkedinText = isNonEmptyString(data.linkedin.postText)
  ? data.linkedin.postText.trim()
  : isNonEmptyString(data.linkedin.content)
  ? data.linkedin.content.trim()
  : '';
if (!linkedinText) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'linkedin.postText' is required and must be a non-empty string." };
}
if (!isStringArray(data.linkedin.hashtags)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'linkedin.hashtags' must be an array of non-empty strings." };
}
const linkedin = {
  postText: linkedinText,
  content: linkedinText,
  hashtags: data.linkedin.hashtags.map(h => h.trim()),
  characterCount: linkedinText.length
};

// 3. Newsletter validation
if (!data.newsletter || typeof data.newsletter !== 'object' || Array.isArray(data.newsletter)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'newsletter' format object is required." };
}
if (!isNonEmptyString(data.newsletter.subject)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'newsletter.subject' is required and must be a non-empty string." };
}
const preview = isNonEmptyString(data.newsletter.previewText)
  ? data.newsletter.previewText.trim()
  : isNonEmptyString(data.newsletter.preview)
  ? data.newsletter.preview.trim()
  : '';
if (!preview) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'newsletter.previewText' is required and must be a non-empty string." };
}
const bodyText = isNonEmptyString(data.newsletter.bodyText)
  ? data.newsletter.bodyText.trim()
  : isNonEmptyString(data.newsletter.body)
  ? data.newsletter.body.trim()
  : '';
if (!bodyText) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'newsletter.bodyText' is required and must be a non-empty string." };
}
const cta = isNonEmptyString(data.newsletter.callToAction)
  ? data.newsletter.callToAction.trim()
  : isNonEmptyString(data.newsletter.cta)
  ? data.newsletter.cta.trim()
  : '';
if (!cta) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'newsletter.callToAction' is required and must be a non-empty string." };
}
const newsletter = {
  subject: data.newsletter.subject.trim(),
  previewText: preview,
  preview: preview,
  bodyText: bodyText,
  body: bodyText,
  callToAction: cta,
  cta: cta
};

// 4. Website validation
if (!data.website || typeof data.website !== 'object' || Array.isArray(data.website)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website' format object is required." };
}
if (!isNonEmptyString(data.website.title)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website.title' is required and must be a non-empty string." };
}
const subtitle = isNonEmptyString(data.website.subtitle)
  ? data.website.subtitle.trim()
  : isNonEmptyString(data.website.excerpt)
  ? data.website.excerpt.trim()
  : '';
if (!subtitle) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website.subtitle' is required and must be a non-empty string." };
}
if (!isNonEmptyString(data.website.slug)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website.slug' is required and must be a non-empty string." };
}
const normalizedSlug = data.website.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
if (!normalizedSlug) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website.slug' contains no valid alphanumeric characters." };
}
const markdown = isNonEmptyString(data.website.bodyMarkdown)
  ? data.website.bodyMarkdown.trim()
  : isNonEmptyString(data.website.markdownContent)
  ? data.website.markdownContent.trim()
  : isNonEmptyString(data.website.markdown)
  ? data.website.markdown.trim()
  : '';
if (!markdown) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website.bodyMarkdown' is required and must be a non-empty string." };
}
if (!isStringArray(data.website.tags)) {
  return { isValid: false, statusCode: 422, error: "Validation error: 'website.tags' must be an array of non-empty strings." };
}
const website = {
  title: data.website.title.trim(),
  subtitle: subtitle,
  excerpt: subtitle,
  slug: normalizedSlug,
  bodyMarkdown: markdown,
  markdownContent: markdown,
  tags: data.website.tags.map(t => t.trim())
};

const generatedId = 'cp_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

return {
  isValid: true,
  id: generatedId,
  title: data.title.trim().slice(0, 255),
  sourcePrompt: prev.sourcePrompt,
  contentType: prev.contentType,
  status: 'draft',
  linkedinContent: JSON.stringify(linkedin),
  newsletterContent: JSON.stringify(newsletter),
  websiteContent: JSON.stringify(website),
  targetChannels: JSON.stringify(prev.targetChannels),
  metadata: JSON.stringify({
    summary: data.summary.trim(),
    generatedVia: 'n8n_gemini_agent',
    generatedAt: new Date().toISOString()
  })
};

const record = $input.item.json;
if (!record || !record.id) {
  throw new Error('Database persistence failed to return a valid content post.');
}

return {
  success: true,
  post: record
};

const post = $input.item.json;
const req = $('Route Action').first().json;

if (!post || !post.id) {
  return {
    canPublish: false,
    statusCode: 404,
    error: 'Not Found: Content post with ID ' + req.postId + ' does not exist.'
  };
}

const isApprovedForPublish =
  (post.status === 'approved' ||
    post.status === 'partially_published' ||
    post.status === 'failed') &&
  post.approvedAt !== null;

if (!isApprovedForPublish) {
  return {
    canPublish: false,
    statusCode: 400,
    error: 'Strict Invariant Violation: Content post cannot be published unless it has been explicitly approved by a human reviewer. Current status is "' + post.status + '".'
  };
}

const SUPPORTED_CHANNELS = ['website', 'linkedin', 'newsletter'];
let approvedChannels = [];
if (Array.isArray(post.targetChannels)) {
  approvedChannels = post.targetChannels;
} else if (typeof post.targetChannels === 'string') {
  try {
    const parsed = JSON.parse(post.targetChannels);
    if (Array.isArray(parsed)) approvedChannels = parsed;
  } catch (e) {
    approvedChannels = ['website', 'linkedin', 'newsletter'];
  }
} else {
  approvedChannels = ['website', 'linkedin', 'newsletter'];
}

let channelsToPublish = approvedChannels;

if (Array.isArray(req.channels) && req.channels.length > 0) {
  for (const ch of req.channels) {
    if (!SUPPORTED_CHANNELS.includes(ch)) {
      return {
        canPublish: false,
        statusCode: 400,
        error: `Invalid channel '${String(ch)}'. Supported channels are: website, linkedin, newsletter.`
      };
    }
  }

  const sortedApproved = [...new Set(approvedChannels)].sort();
  const sortedRequested = [...new Set(req.channels)].sort();

  if (post.status === 'approved') {
    const matchesApproved =
      sortedApproved.length === sortedRequested.length &&
      sortedApproved.every((ch, i) => ch === sortedRequested[i]);

    if (!matchesApproved) {
      return {
        canPublish: false,
        statusCode: 400,
        error: `Channel selection mismatch: Requested channels [${sortedRequested.join(', ')}] do not match the approved channel selection [${sortedApproved.join(', ')}]. Channel modifications require renewed approval before publication.`
      };
    }
  } else {
    const unapproved = sortedRequested.find(ch => !approvedChannels.includes(ch));
    if (unapproved) {
      return {
        canPublish: false,
        statusCode: 400,
        error: `Channel selection mismatch: Requested channel '${unapproved}' is not part of the approved channel selection [${sortedApproved.join(', ')}]. Channel modifications require renewed approval before publication.`
      };
    }
  }

  channelsToPublish = sortedRequested;
}

// Deduplicate against existing successful logs
const alreadyPublishedLogs = [];
const existingLogs = Array.isArray(post.existingLogs) ? post.existingLogs : [];
const alreadyPublishedChannels = new Set();

for (const log of existingLogs) {
  if (log.status === 'published' || log.status === 'success') {
    alreadyPublishedChannels.add(log.channel);
    alreadyPublishedLogs.push(log);
  }
}

const channelsToDispatch = channelsToPublish.filter(ch => !alreadyPublishedChannels.has(ch));

return {
  canPublish: true,
  postId: post.id,
  title: post.title,
  approvedChannels,
  channelsToPublish,
  channelsToDispatch,
  hasChannelsToDispatch: channelsToDispatch.length > 0,
  alreadyPublishedLogs,
  websiteContent: post.websiteContent,
  linkedinContent: post.linkedinContent,
  newsletterContent: post.newsletterContent
};

const prep = $input.item.json;
const channels = prep.channelsToDispatch || [];
let baseUrl = 'http://localhost:3000';
try {
  baseUrl = ($env.SANDBOX_BASE_URL || 'http://localhost:3000').replace(/\/+$/, '');
} catch (e) {
  baseUrl = 'http://localhost:3000';
}

let apiKey = 'sandbox_demo_secret_key';
try {
  if (typeof $env !== 'undefined' && $env.SANDBOX_API_KEY) {
    apiKey = $env.SANDBOX_API_KEY;
  }
} catch (e) {
  apiKey = 'sandbox_demo_secret_key';
}

const items = [];

let web = {};
try { web = typeof prep.websiteContent === 'string' ? JSON.parse(prep.websiteContent) : (prep.websiteContent || {}); } catch(e) {}
let li = {};
try { li = typeof prep.linkedinContent === 'string' ? JSON.parse(prep.linkedinContent) : (prep.linkedinContent || {}); } catch(e) {}
let nl = {};
try { nl = typeof prep.newsletterContent === 'string' ? JSON.parse(prep.newsletterContent) : (prep.newsletterContent || {}); } catch(e) {}

for (const ch of channels) {
  let endpointUrl = '';
  let bodyData = {};

  if (ch === 'website') {
    endpointUrl = `${baseUrl}/api/sandbox/cms/posts`;
    bodyData = {
      title: web.title || prep.title,
      slug: web.slug || ('post-' + prep.postId),
      content: web.bodyMarkdown || web.markdownContent || '',
      status: 'publish',
      tags: Array.isArray(web.tags) ? web.tags : []
    };
  } else if (ch === 'linkedin') {
    endpointUrl = `${baseUrl}/api/sandbox/linkedin/posts`;
    bodyData = {
      text: li.postText || li.content || prep.title,
      hashtags: Array.isArray(li.hashtags) ? li.hashtags : []
    };
  } else if (ch === 'newsletter') {
    endpointUrl = `${baseUrl}/api/sandbox/newsletter/send`;
    bodyData = {
      subject: nl.subject || prep.title,
      preview: nl.previewText || nl.preview || '',
      body: nl.bodyText || nl.body || '',
      cta: nl.callToAction || nl.cta || ''
    };
  }

  items.push({
    json: {
      postId: prep.postId,
      channel: ch,
      endpointUrl,
      authHeader: 'Bearer ' + apiKey,
      bodyData
    }
  });
}

return items;

const items = $input.all();
const prepNode = $('Verify Human Approval & Prepare Channels').first().json;
const approvedChannels = prepNode.approvedChannels || ['website', 'linkedin', 'newsletter'];
const alreadyPublishedLogs = prepNode.alreadyPublishedLogs || [];
const postId = prepNode.postId;

const newLogs = [];
const successfulChannelNames = new Set();

for (const log of alreadyPublishedLogs) {
  if (log.status === 'published' || log.status === 'success') {
    successfulChannelNames.add(log.channel);
  }
}

if (prepNode.hasChannelsToDispatch) {
  for (let i = 0; i < items.length; i++) {
    const item = items[i].json;
    let dispatchMeta = {};
    try {
      dispatchMeta = $('Format Dispatch Items').itemMatching(i).json;
    } catch (e) {
      dispatchMeta = item;
    }

    const channel = dispatchMeta.channel;
    if (!channel) continue;

    const statusCode = Number(item.statusCode || (item.error ? 500 : 200));
    const isSuccess = statusCode >= 200 && statusCode < 300;

    let responseBody = item.body;
    if (typeof responseBody === 'string') {
      try { responseBody = JSON.parse(responseBody); } catch (e) {}
    }

    let publishedUrl = null;
    let errorMessage = null;

    if (isSuccess) {
      successfulChannelNames.add(channel);
      publishedUrl = responseBody?.link || responseBody?.url || responseBody?.shareUrl || null;
    } else {
      const errorText = (typeof responseBody === 'object' && responseBody?.error)
        ? responseBody.error
        : (item.error?.message || (typeof item.error === 'string' ? item.error : null) || item.statusMessage || String(responseBody || 'Dispatch failed'));
      errorMessage = `${channel.toUpperCase()} API responded with ${statusCode}: ${errorText}`;
    }

    const logId = 'log_' + Date.now().toString(36) + '_' + channel + '_' + Math.random().toString(36).substring(2, 6);

    newLogs.push({
      id: logId,
      post_id: postId,
      postId: postId,
      channel: channel,
      status: isSuccess ? 'published' : 'failed',
      published_url: publishedUrl,
      publishedUrl: publishedUrl,
      response_payload: JSON.stringify(responseBody || {}),
      responsePayload: JSON.stringify(responseBody || {}),
      error_message: errorMessage,
      errorMessage: errorMessage
    });
  }
}

const allApprovedSuccess = approvedChannels.every(ch => successfulChannelNames.has(ch));
const anyApprovedSuccess = approvedChannels.some(ch => successfulChannelNames.has(ch));

let newStatus = 'failed';
if (allApprovedSuccess) {
  newStatus = 'published';
} else if (anyApprovedSuccess) {
  newStatus = 'partially_published';
} else {
  newStatus = 'failed';
}

return {
  success: anyApprovedSuccess,
  postId,
  newStatus,
  logs: newLogs,
  logsJson: JSON.stringify(newLogs),
  hasNewLogs: newLogs.length > 0,
  publishedChannels: Array.from(successfulChannelNames)
};

const updatedPost = $input.item.json;
const outcomes = $('Aggregate Outcomes & Finalize Status').first().json;

return {
  success: true,
  postId: outcomes.postId,
  status: updatedPost?.status || outcomes.newStatus || 'published',
  publishedChannels: outcomes.publishedChannels,
  logs: outcomes.logs
};

const item = $input.item.json;
const errObj = item?.error || item;
const errStatus = Number(errObj?.status || errObj?.statusCode || 0);
const rawMessage = String(errObj?.message || errObj?.description || item?.message || '');

const isRateLimit =
  errStatus === 429 ||
  rawMessage.includes('429') ||
  rawMessage.toLowerCase().includes('too many requests') ||
  rawMessage.toLowerCase().includes('quota');

const isUnavailable =
  errStatus === 503 ||
  rawMessage.includes('503') ||
  rawMessage.toLowerCase().includes('service unavailable');

let statusCode = 502;
let safeMessage = 'AI content generation service failed to produce content.';

if (isRateLimit) {
  statusCode = 429;
  safeMessage = 'AI content generation rate limit reached. Please retry shortly.';
} else if (isUnavailable) {
  statusCode = 503;
  safeMessage = 'AI content generation service temporarily unavailable. Please retry shortly.';
}

return {
  success: false,
  error: safeMessage,
  statusCode
};

return {
  success: false,
  error: 'Database operation failed during content pipeline execution. Please try again.',
  statusCode: 500
};
